import{_ as d,C as s,o as n,c as r,aj as e,E as o}from"./framework.js";const u=JSON.parse('{"title":"IndexedDB Tables | Database | Admin CMS","description":"IndexedDB tables are the site’s built-in dynamic table storage: after defining table names and fields (columns) in the admin, you maintain data on this page and read/write in KScript…","frontmatter":{"title":"IndexedDB Tables | Database | Admin CMS","description":"IndexedDB tables are the site’s built-in dynamic table storage: after defining table names and fields (columns) in the admin, you maintain data on this page and read/write in KScript…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/database/table.html"}]]},"headers":[],"relativePath":"cms/database/table.md","filePath":"en/cms/database/table.md","lastUpdated":1781010536000}'),i={name:"cms/database/table.md"};function l(h,t,c,b,g,p){const a=s("DocImage");return n(),r("div",null,[t[0]||(t[0]=e('<h1 id="indexeddb-tables" tabindex="-1">IndexedDB Tables <a class="header-anchor" href="#indexeddb-tables" aria-label="Permalink to &quot;IndexedDB Tables&quot;">​</a></h1><blockquote><p>Menu: <strong>Database → IndexedDB Tables</strong><br> Deep link: <code>/_Admin/database/table?SiteId={siteGuid}</code></p></blockquote><p><strong>IndexedDB tables</strong> are the site’s built-in <strong>dynamic table</strong> storage: after defining table names and fields (columns) in the admin, you maintain data on this page and read/write in KScript through <strong><code>k.DB.indexedDb.{tableName}</code></strong>. Data is isolated per site; no separate connection string is required.</p><div class="tip custom-block"><p class="custom-block-title">Permissions</p><p>List and browse data: <code>database</code> (view). <strong>Create table</strong>, change columns, and create/update/delete data require <code>database·edit</code>; multi-select delete of tables or rows requires <code>database·delete</code>.</p></div><div class="info custom-block"><p class="custom-block-title">Difference from SQLite / MySQL menus</p><table tabindex="0"><thead><tr><th></th><th><strong>IndexedDB tables</strong></th><th><strong>SQLite tables</strong>, etc.</th></tr></thead><tbody><tr><td>Storage</td><td>Site IndexedDB dynamic tables</td><td>Site SQLite file or external database connections</td></tr><tr><td>Create table</td><td>Enter table name in admin</td><td>SQLite works out of the box; MySQL/SQL Server require connection setup first</td></tr><tr><td>Change schema</td><td>Maintain fields on <strong>Column settings</strong> page</td><td>Mostly existing physical tables; capabilities depend on the UI</td></tr><tr><td>Script</td><td><code>k.DB.indexedDb.tableName</code></td><td><code>k.DB.sqlite</code>, etc.</td></tr></tbody></table><p>See <a href="./">Database overview</a>.</p></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In <a href="./../navigation.html#permissions-and-edit-menu">Edit Menu</a>, check <strong>Database → IndexedDB Tables</strong>.</li><li>Open <strong>Database → IndexedDB Tables</strong> in the left sidebar.</li></ol>',7)),o(a,{src:"/cms/database/table-overview.png",alt:"IndexedDB table list",width:"1120"}),t[1]||(t[1]=e('<h2 id="table-list" tabindex="-1">Table List <a class="header-anchor" href="#table-list" aria-label="Permalink to &quot;Table List&quot;">​</a></h2><h3 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>Create table</strong></td><td><code>database·edit</code></td><td>Opens the <a href="#create-table-dialog">create table dialog</a></td></tr></tbody></table>',3)),o(a,{src:"/cms/database/table-toolbar.png",alt:"Table list toolbar",width:"1120"}),t[2]||(t[2]=e('<h3 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column / action</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Click the table name to open <a href="#table-data">table data</a></td></tr><tr><td>Row <strong>Settings</strong> (gear)</td><td>Opens <a href="#column-settings">column settings</a></td></tr><tr><td>Multi-select <strong>Delete</strong></td><td>Deletes the entire table and its data (<code>database·delete</code>)</td></tr></tbody></table><p>System internal table names starting with <code>_sys_</code> or <code>_koobootemp</code> are not shown in the list.</p>',3)),o(a,{src:"/cms/database/table-list.png",alt:"Table list",width:"1120"}),t[3]||(t[3]=e('<h3 id="create-table-dialog" tabindex="-1">Create table dialog <a class="header-anchor" href="#create-table-dialog" aria-label="Permalink to &quot;Create table dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Rule</th></tr></thead><tbody><tr><td><strong>Table name</strong></td><td>Required; 1–50 characters; must start with a letter or digit; letters and digits only; unique within the site</td></tr></tbody></table><p>After confirmation, the table definition is registered. You can open <strong>Column settings</strong> to add fields, or click the table name to maintain data directly (empty tables can receive data first; columns take effect when <strong>Column settings</strong> is saved).</p>',3)),o(a,{src:"/cms/database/table-create-dialog.png",alt:"Create table dialog",width:"1120"}),t[4]||(t[4]=e('<h2 id="column-settings" tabindex="-1">Column Settings <a class="header-anchor" href="#column-settings" aria-label="Permalink to &quot;Column Settings&quot;">​</a></h2><p>Route: <code>/_Admin/database/table/columns?SiteId=...&amp;table={tableName}</code></p><p>Enter from list <strong>Settings</strong>, or from <strong>Settings</strong> on the <strong>Table data</strong> toolbar. The page header shows the current table name.</p><h3 id="toolbar-1" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar-1" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Description</th></tr></thead><tbody><tr><td><strong>New column</strong></td><td>Opens the <a href="#column-editor-dialog">column editor dialog</a></td></tr></tbody></table><h3 id="column-list" tabindex="-1">Column list <a class="header-anchor" href="#column-list" aria-label="Permalink to &quot;Column list&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Column name</strong></td><td>Field name</td></tr><tr><td><strong>Control type</strong></td><td>See table below</td></tr><tr><td><strong>Primary key</strong> / <strong>Unique</strong></td><td>Shown only for IndexedDB tables</td></tr><tr><td><strong>Index</strong></td><td>Whether an index is created (primary key columns are treated as indexed)</td></tr><tr><td><strong>Edit</strong> / <strong>Delete</strong></td><td>Change column definition; remove column from list (effective after save)</td></tr></tbody></table><p>Bottom <strong>Save</strong> / <strong>Cancel</strong>: <strong>Save</strong> writes the full column definition back to the site; unsaved changes prompt before leaving. Internal fields <strong><code>_id</code></strong> (primary key) and <strong><code>_version</code></strong> are not shown in the list.</p>',8)),o(a,{src:"/cms/database/table-columns.png",alt:"Column settings list",width:"1120"}),t[5]||(t[5]=e('<h3 id="column-editor-dialog" tabindex="-1">Column editor dialog <a class="header-anchor" href="#column-editor-dialog" aria-label="Permalink to &quot;Column editor dialog&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Required when creating; cannot be renamed after save</td></tr><tr><td><strong>Control type</strong></td><td>Determines data type and input control (see below)</td></tr><tr><td><strong>Length</strong></td><td>Max length for text controls</td></tr><tr><td><strong>Options</strong></td><td><strong>Select / checkbox / radio</strong> require display name and value</td></tr><tr><td><strong>Auto-increment</strong></td><td><strong>Number</strong> type only: increments by seed and step; not editable on the data edit page</td></tr><tr><td><strong>Primary key</strong></td><td>Business primary key marker (coexists with system <code>_id</code>; use per table design)</td></tr><tr><td><strong>Unique</strong></td><td>Column values must be unique</td></tr><tr><td><strong>Index</strong></td><td>Query index</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Control type (UI)</th><th>Typical use</th></tr></thead><tbody><tr><td>Text box</td><td>Short text</td></tr><tr><td>Textarea</td><td>Long text</td></tr><tr><td>Rich text</td><td>HTML content</td></tr><tr><td>Select / checkbox / radio</td><td>Enumerated options</td></tr><tr><td>Boolean</td><td>Yes/no</td></tr><tr><td>Date-time</td><td>Date and time</td></tr><tr><td>Number</td><td>Numeric values; can auto-increment</td></tr></tbody></table>',3)),o(a,{src:"/cms/database/table-column-dialog.png",alt:"Column editor dialog",width:"1120"}),t[6]||(t[6]=e('<h2 id="table-data" tabindex="-1">Table Data <a class="header-anchor" href="#table-data" aria-label="Permalink to &quot;Table Data&quot;">​</a></h2><p>Route: <code>/_Admin/database/table/data?SiteId=...&amp;table={tableName}</code></p><p>Click a <strong>table name</strong> in the list to open.</p><h3 id="toolbar-2" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar-2" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><strong>New data</strong></td><td><code>database·edit</code></td><td>Opens <a href="#edit-data">edit data</a> (create)</td></tr><tr><td><strong>Export data</strong></td><td><code>database</code> (view)</td><td>Exports current filter/sort data as <strong>CSV</strong></td></tr><tr><td><strong>Settings</strong></td><td>—</td><td>Jump to <strong>Column settings</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">No CSV import</p><p>The <strong>IndexedDB tables</strong> data page does <strong>not</strong> provide an <strong>Import data</strong> button (that feature is on SQLite / MySQL / SQL Server table menus). For bulk writes use script <code>k.DB.indexedDb</code> or custom import logic.</p></div>',6)),o(a,{src:"/cms/database/table-data-toolbar.png",alt:"Table data toolbar",width:"1120"}),t[7]||(t[7]=e('<h3 id="data-table" tabindex="-1">Data table <a class="header-anchor" href="#data-table" aria-label="Permalink to &quot;Data table&quot;">​</a></h3><ul><li>Columns: business fields except <strong><code>_id</code></strong> and <strong><code>_version</code></strong>; headers support <strong>sorting</strong> (sort state is saved locally in the browser).</li><li>Pagination: default <strong>30</strong> rows per page; page through results.</li><li>Row <strong>Edit</strong>: opens <a href="#edit-data">edit data</a>.</li><li>Multi-select <strong>Delete</strong>: deletes rows by primary key (<code>database·delete</code>).</li></ul><p>Date-time columns are formatted as local time in the list.</p>',3)),o(a,{src:"/cms/database/table-data.png",alt:"Table data list",width:"1120"}),t[8]||(t[8]=e(`<h2 id="edit-data" tabindex="-1">Edit Data <a class="header-anchor" href="#edit-data" aria-label="Permalink to &quot;Edit Data&quot;">​</a></h2><p>Route: <code>/_Admin/database/table/edit-data?SiteId=...&amp;table={tableName}</code> (no <code>id</code> when creating; <code>id</code> when editing)</p><p>Form fields are rendered by <strong>control type</strong> from <strong>Column settings</strong>: text, rich text, options, boolean, date-time, number, etc. <strong>Auto-increment</strong> fields show the current value only and cannot be edited.</p><p><strong>Save</strong> returns to the <strong>Table data</strong> list; <strong>Cancel</strong> discards and returns.</p><h2 id="script-access-development" tabindex="-1">Script access (development) <a class="header-anchor" href="#script-access-development" aria-label="Permalink to &quot;Script access (development)&quot;">​</a></h2><p>In Code / module server-side scripts, access tables as properties of <code>k.DB.indexedDb</code>, for example:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> row</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.indexedDb.orders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;orderNo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.indexedDb.orders.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ orderNo: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1002&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, amount: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">99</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>Chained APIs (<code>find</code> / <code>findAll</code> / <code>add</code> / <code>update</code> / <code>delete</code> / <code>pagination</code>, etc.) are documented in <strong><a href="/kb-docs/api/indexed-db/">k.DB.indexedDb</a></strong>. Column and data changes made in the admin use the same tables as scripts.</p><div class="tip custom-block"><p class="custom-block-title">SQL logs</p><p>IndexedDB operations are <strong>not</strong> written to SQL logs. Only SQL from <code>k.DB.sqlite</code> / MySQL / SQL Server appears in <a href="./sql-logs.html">SQL logs</a> when site <strong>SQL logging</strong> is enabled.</p></div><h2 id="typical-workflow" tabindex="-1">Typical workflow <a class="header-anchor" href="#typical-workflow" aria-label="Permalink to &quot;Typical workflow&quot;">​</a></h2><ol><li><strong>Create table</strong> with a valid table name.</li><li>Open <strong>Settings</strong>, <strong>New column</strong>, and <strong>Save</strong> the column definition.</li><li>Click the table name, <strong>New data</strong> to enter records, or write via script.</li><li>For multi-table associations, configure <a href="./table-relation.html">IndexedDB table relations</a>.</li><li>For troubleshooting or auditing, see <a href="./sql-logs.html">SQL logs</a>.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./">Database overview</a></td><td>Submenus and routes</td></tr><tr><td><a href="./table-relation.html">IndexedDB table relations</a></td><td>Table associations</td></tr><tr><td><a href="/kb-docs/api/indexed-db/">k.DB.indexedDb</a></td><td>Full script API</td></tr><tr><td><a href="./../development/code.html">Development · Code</a></td><td>Writing Code that calls tables</td></tr></tbody></table>`,13))])}const k=d(i,[["render",l]]);export{u as __pageData,k as default};
